declare cid uuid;
begin
  select id into cid from public.courses where slug = 'spanish-2';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 19, $j$5.3 Careers, Technology and the Interview$j$, $j${"readings": [{"title": "Colossians 3 (King James Version)", "url": "/portal/bible/Colossians/3"}], "body": "Colossians 3:23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men. God values every honest job. Learning career and technology vocabulary in Spanish prepares you to work with Spanish speaking coworkers and customers.\n\nCareers include el médico, la enfermera, el maestro, la maestra, el ingeniero, el abogado, el pastor, el mecánico, el electricista, el programador, la cocinera, el contador and el empresario. Note that many nouns for people keep the same form for male or female, such as el estudiante and la estudiante, and the article shows gender.\n\nTechnology words are la computadora, el teléfono, el correo electrónico, el sitio web, la aplicación, la contraseña, el archivo and la pantalla. Never share your contraseña.\n\nFor an interview, useful phrases are Me llamo and Tengo experiencia en. Me gustaría trabajar con ustedes means I would like to work with you. Trabajo bien en equipo means I work well on a team. Estoy aprendiendo español means I am learning Spanish. Use usted in an interview and end with Gracias por su tiempo.\n\nWorked example: Buenos días. Me llamo Daniel. Me gustaría ser programador. Estudio computación y trabajo bien en equipo. Common mistake: using a tú form with an interviewer. Use usted and a polite tone.\n\nYour task: (1) Write a six sentence introduction for a job interview in Spanish. (2) List ten careers and one thing each person does.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Colossians 3:23 says, Whatsoever ye do, do it heartily, as to the Lord. God values every honest job.\n\nNow watch this. Careers: el médico, la enfermera, el maestro, el ingeniero, el abogado, el pastor, el mecánico, el programador, la cocinera.\n\nTechnology: la computadora, el teléfono, el correo electrónico, el sitio web, la aplicación, la contraseña. Never share your contraseña.\n\nInterview phrases: Me llamo. Tengo experiencia en. Me gustaría trabajar con ustedes. Trabajo bien en equipo. Use usted and finish with Gracias por su tiempo.\n\nYour task is to write a six sentence interview introduction and list ten careers. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.3 Careers, Technology and the Interview$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 20, $j$5.4 Holidays, Traditions and Cultural Respect$j$, $j${"readings": [{"title": "Luke 2 (King James Version)", "url": "/portal/bible/Luke/2"}], "body": "Luke 2:10 says, And the angel said unto them, Fear not: for, behold, I bring you good tidings of great joy, which shall be to all people. In the Spanish speaking world, the story of Christmas is celebrated in many beautiful ways, and learning about traditions helps us love our neighbors.\n\nNavidad is Christmas. Nochebuena, Christmas Eve, is often the main family celebration, with a late dinner and church. In many countries, children receive gifts on el Día de los Reyes Magos, January 6, remembering the wise men. Semana Santa, Holy Week, includes services and processions leading to Pascua, Easter. A quinceañera celebrates a girl's fifteenth birthday, often beginning with a church service of thanks. Families gather around foods such as tamales, pan dulce, arroz con pollo and buñuelos.\n\nEach country has its own customs. A Cuban family in Florida may serve lechón on Nochebuena. A Mexican family may share tamales. A Puerto Rican family may sing parrandas. Never assume that all Spanish speakers are the same.\n\nSome traditions mix older cultural and religious customs. A Christian student can study them to understand and respect neighbors, while keeping his own convictions rooted in the Bible. Ask kindly: ¿Cómo celebran ustedes la Navidad?\n\nWorked example: En mi familia, celebramos la Nochebuena con una cena y vamos a la iglesia. Common mistake: using one tradition to describe an entire people. Name the country or community.\n\nYour task: (1) Write six sentences about how your family celebrates one holiday. (2) Write three respectful questions you could ask a Spanish speaking neighbor about their traditions.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Luke 2:10 says, Fear not: for, behold, I bring you good tidings of great joy, which shall be to all people. Let us learn how Spanish speaking families celebrate.\n\nNow watch this. Navidad is Christmas. Nochebuena is Christmas Eve, often the main family celebration. El Día de los Reyes Magos is January 6. Semana Santa is Holy Week, and Pascua is Easter. A quinceañera celebrates a girl's fifteenth birthday.\n\nFoods: tamales, pan dulce, arroz con pollo, buñuelos.\n\nEach country has its own customs. Name the country or community, and do not assume that all Spanish speakers are the same.\n\nWe study traditions to understand and respect neighbors, while keeping our convictions rooted in the Bible. Ask kindly. ¿Cómo celebran ustedes la Navidad?\n\nYour task is to write six sentences about your family holiday and three respectful questions. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.4 Holidays, Traditions and Cultural Respect$j$);
end
